<?php
require_once __DIR__.'/../includes/admin-functions.php';
$schema=dental_schema($pdo);$labId=$schema->labId();$serviceId=$schema->serviceId();$serviceName=$schema->serviceName();$imageId=$schema->imageId();$imagePath=$schema->imagePath();$hasDocument=$schema->hasDocument();$hasLabDate=$schema->hasCreatedAt();$hasImageDate=$schema->hasCreatedAt('image_laboratoire');
$docSelect=$hasDocument?'l.document_verification':'NULL AS document_verification';$dateSelect=$hasLabDate?'l.created_at':'NULL AS created_at';$imageSort=$hasImageDate?'i.created_at,':'';$labSort=$hasLabDate?'l.created_at ASC,':'';
$sql="SELECT l.`$labId` id,l.nom_laboratoire,l.nom_gerant,l.email,l.telephone,l.adresse,l.ville,l.description,$docSelect,$dateSelect,(SELECT GROUP_CONCAT(s.`$serviceName` ORDER BY s.`$serviceName` SEPARATOR ', ') FROM laboratoire_service ls JOIN service s ON s.`$serviceId`=ls.service_id WHERE ls.laboratoire_id=l.`$labId`) services FROM laboratoire l WHERE l.statut=? ORDER BY $labSort l.`$labId` ASC";
$q=$pdo->prepare($sql);$q->execute([$schema->status('en_attente')]);$labs=$q->fetchAll();
$pageTitle='Validation des inscriptions';$assetPrefix='../';$navContext='admin';$pageStyles=['assets/css/admin.css'];$pageScripts=['assets/js/admin.js'];require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/navbar.php';$flash=admin_take_flash();
?>
<main class="admin-main"><div class="admin-heading"><div><p class="admin-eyebrow">Modération</p><h1>Inscriptions à vérifier</h1><p class="admin-muted"><?=count($labs)?> dossier(s) en attente.</p></div></div><?php if($flash):?><div class="admin-alert <?=e($flash['type'])?>"><?=e($flash['message'])?></div><?php endif;?><?php if(!$labs):?><section class="admin-panel empty-state"><h2>Aucun dossier en attente</h2><p>Les nouvelles inscriptions apparaîtront ici.</p></section><?php endif;?>
<div class="review-list"><?php foreach($labs as $lab):?><article class="admin-panel review-card"><div class="review-head"><div><span class="status-badge status-en_attente">En attente</span><h2><?=e($lab['nom_laboratoire'])?></h2><p class="admin-muted"><?=$lab['created_at']?'Inscrit le '.e(date('d/m/Y à H:i',strtotime($lab['created_at']))):'Date indisponible'?></p></div><a class="admin-button admin-secondary" href="laboratoires.php?id=<?=$lab['id']?>">Ouvrir le dossier</a></div><div class="review-details"><p><strong>Gérant</strong><?=e($lab['nom_gerant'])?></p><p><strong>E-mail</strong><a href="mailto:<?=e($lab['email'])?>"><?=e($lab['email'])?></a></p><p><strong>Téléphone</strong><a href="tel:<?=e($lab['telephone'])?>"><?=e($lab['telephone'])?></a></p><p><strong>Ville</strong><?=e($lab['ville'])?></p><p><strong>Adresse</strong><?=e($lab['adresse'])?></p><p><strong>Services</strong><?=e($lab['services']??'—')?></p><p class="review-description"><strong>Description</strong><?=nl2br(e($lab['description']))?></p></div><div class="review-files"><?php if($lab['document_verification']):?><a class="admin-button admin-secondary" href="document.php?id=<?=$lab['id']?>" target="_blank" rel="noopener">Voir le document de vérification (privé)</a><?php else:?><span class="admin-muted">Aucun document.</span><?php endif;?><?php $images=$pdo->prepare("SELECT `$imagePath` FROM image_laboratoire WHERE laboratoire_id=? ");$images->execute([$lab['id']]);foreach($images->fetchAll(PDO::FETCH_COLUMN) as $image):?><a href="../<?=e($image)?>" target="_blank" rel="noopener"><img src="../<?=e($image)?>" alt="Photo de <?=e($lab['nom_laboratoire'])?>"></a><?php endforeach;?></div><div class="review-actions"><form method="post" action="../crud/update.php" data-confirm="Valider ce laboratoire et le rendre visible dans l’annuaire ?"><?=csrf_field()?><input type="hidden" name="laboratoire_id" value="<?=$lab['id']?>"><button class="admin-button admin-green" name="statut" value="valide">Valider</button></form><form method="post" action="../crud/update.php" data-confirm="Rejeter cette inscription ?"><?=csrf_field()?><input type="hidden" name="laboratoire_id" value="<?=$lab['id']?>"><button class="admin-button admin-red" name="statut" value="rejete">Rejeter</button></form></div></article><?php endforeach;?></div></main><?php require __DIR__.'/../includes/footer.php'; ?>
